async fn cleanup_sweep_once(&self, attempt: usize) -> bool {
  let mut any_deferred = false;
  for session in self.account_manager.sessions_iter() {
    match session.key_packages().cleanup_relay_key_packages_once().await {
      Ok(AlreadyCompleted) => { /* debug log */ }
      Ok(DeferredRecentConsumedKeyPackage) => { any_deferred = true; /* info log */ }
      Ok(DeletedAndPublished { deleted }) => { /* info log */ }
      Err(error) => { /* warn log */ }
    }
  }
  any_deferred
}
